                                        for y in range(j,j+3)]
                    if not is_valid(square):
                        return False
            return True

        def is_valid(value):
            res=[i for i in value if i!="."]
            return len(res)==len(set(res))

        return is_valid_row() and is_valid_col() and is_valid_square()

