                        if (flag[board[x + j][y + k] - '1'] == true)
                            return false;
                        flag[board[x + j][y + k] - '1'] = true;
                    }
                }
            }
        }
        return true;
    }
}

class Solution(object):
    def isValidSudoku(self, board):
        """
        :type board: List[List[str]]
        :rtype: bool
        """
        for i in range(9):
            t = []
            for j in range(9):
                if board[i][j] != ".":
                    if board[i][j] in t:
                        return False
                    t.append(board[i][j])
            t = []
            for j in range(9):
                if board[j][i] != ".":
                    if board[j][i] in t:
                        return False
                    t.append(board[j][i])
            t = []
            x, y = i // 3 * 3, i % 3 * 3
            for j in range(3):
                for k in range(3):
                    if board[x + j][y + k] != ".":
                        if board[x + j][y + k] in t:
                            return False
                        t.append(board[x + j][y + k])
        return True
